CREATE TABLE clientes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255) NOT NULL, cnpj VARCHAR(255), email VARCHAR(255), telefone VARCHAR(255));
CREATE TABLE viagens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero VARCHAR(255) NOT NULL, data DATE, status VARCHAR(255), cliente_id BIGINT NOT NULL, CONSTRAINT fk_viagem_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id));
CREATE TABLE documentos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_arquivo VARCHAR(255) NOT NULL, tipo VARCHAR(255) NOT NULL, caminho VARCHAR(255) NOT NULL, viagem_id BIGINT NOT NULL, CONSTRAINT fk_documento_viagem FOREIGN KEY (viagem_id) REFERENCES viagens(id));
CREATE TABLE envios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, viagem_id BIGINT NOT NULL, cliente_id BIGINT NOT NULL, data_envio TIMESTAMP(6), status VARCHAR(255), mensagem VARCHAR(255), CONSTRAINT fk_envio_viagem FOREIGN KEY (viagem_id) REFERENCES viagens(id), CONSTRAINT fk_envio_cliente FOREIGN KEY (cliente_id) REFERENCES clientes(id));
CREATE INDEX idx_viagens_cliente ON viagens(cliente_id);
CREATE INDEX idx_documentos_viagem ON documentos(viagem_id);
CREATE INDEX idx_envios_viagem ON envios(viagem_id);
